# node ingested by Cartography carries `_module_name` (e.g. `cartography:aws`)
# and `_module_version` properties; Prowler's own nodes use `cartography:prowler`
# and the ontology module uses `cartography:ontology`, both of which are ignored.
CARTOGRAPHY_SCHEMA_QUERY = """
    MATCH (n {provider_id: $provider_id})
    WHERE n._module_name STARTS WITH 'cartography:'
